# Faithful translation of the single easy-band selection branch, preserving the
# engine's deduped BTreeSet order, SHA-256 seed, uniform draw bytes 8..16 and history.
def select_easy(pool,seed,seen=()):
 pool=sorted(set(pool)-set(seen));h=hashlib.sha256(('course-academy/question-selection/v1/'+seed).encode()).digest()
 u=(int.from_bytes(h[8:16],'big')>>11)/(1<<53)
 return pool[int(u*len(pool))] if pool else None
