 lookup={i:r for i,r in enumerate(poolrecords,1)}
 draws=[lookup[select_easy(list(lookup),'independent-'+str(k))] for k in range(128)]
 out.append({'pool':name,'policy':'Conditional on a configured positive easy-band weight and no prior seen questions. Engine draws uniformly within the selected rated band. Entity order uses proxy IDs 1..N; predictor holds for every eligible record, so this ordering cannot rescue the shortcut.','draws':128,'shortcut':rev.shape_probe(draws),'without_replacement_sequence':[select_easy(list(lookup),'sequence-'+str(k),seen=range(1,k+1)) for k in range(len(lookup))]})
